// Garante que a saída do Agente seja um JSON válido e parseável.
// Com o Structured Output Parser conectado, $json.output normalmente já
// vem como objeto; este código também cobre o caso de vir como texto
// (com blocos ```json, crases ou texto extra ao redor).
const item = $input.first().json;

let raw = item.output ?? item.text ?? item.content ?? '';

// Se o parser já devolveu um objeto estruturado, usa direto
if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
  return [{
    json: {
      cliente_nome: raw.cliente_nome ?? '',
      descricao_problema: raw.descricao_problema ?? '',
      exemplo_pedido: raw.exemplo_pedido ?? '',
      testes_realizados: raw.testes_realizados ?? '',
      tema: raw.tema ?? ''
    }
  }];
}

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw);
}

// Remove blocos de código markdown e crases soltas
let cleaned = raw
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .replace(/`/g, '')
  .trim();

// Isola apenas o objeto JSON mais externo, caso haja texto ao redor
const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
  cleaned = cleaned.substring(firstBrace, lastBrace + 1);
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  parsed = {
    cliente_nome: '',
    descricao_problema: '',
    exemplo_pedido: '',
    testes_realizados: '',
    tema: '',
    erro: 'Não foi possível interpretar a resposta da IA como JSON.',
    resposta_bruta: raw
  };
}

const resultado = {
  cliente_nome: parsed.cliente_nome ?? '',
  descricao_problema: parsed.descricao_problema ?? '',
  exemplo_pedido: parsed.exemplo_pedido ?? '',
  testes_realizados: parsed.testes_realizados ?? '',
  tema: parsed.tema ?? ''
};

return [{ json: resultado }];
